from pathlib import Path
import json, html
r=Path(__file__).resolve().parents[1]
A='/assets/royal-sanctuary/'
manifest=json.loads((r/'docs/template-imports/royal-sanctuary.assets.json').read_text(encoding='utf-8'))
def asset(name):
 return next(a['local'] for a in manifest['assets'] if a['source'].split('?')[0].endswith('/'+name))
def img(name,classes='',alt='',extra=''):
 return f'<img src="{asset(name)}" class="{classes}" alt="{alt}" {extra}>'
