extra='''html,body{margin:0;scroll-behavior:smooth}body{font-family:Poppins,sans-serif;color:#6b4f2c;background:radial-gradient(circle,#fdfaf7,#f4eae1);--font-serif:"Playfair Display",Georgia,serif;--font-sans:Poppins,sans-serif}main{position:relative;width:100%;max-width:430px;margin:auto;min-height:100svh;overflow-x:hidden;background:#fdfaf5;box-shadow:0 0 50px #8b73550f;border-inline:1px solid #c9953a40}body.closed{overflow:hidden}body.closed main{height:100svh;overflow:hidden}.font-serif{font-family:"Playfair Display",Georgia,serif}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #8c251e;outline-offset:4px}#opening{transition:opacity .7s}#opening[hidden]{display:none}.sanctuary-hero{height:100svh}.hero-copy{position:absolute;z-index:2;top:9%;left:5%;right:5%;text-align:center}.hero-eyebrow{margin:0 0 18px;color:#996014;font-size:10px;font-weight:700;letter-spacing:.4em;text-transform:uppercase}.hero-names{margin:0;color:#6b4f2c;font:italic 500 clamp(42px,13vw,64px)/1.08 'Playfair Display',Georgia,serif;overflow-wrap:anywhere}.hero-names>[data-field]{display:block}.hero-ampersand{display:block;margin:10px 0 14px;font:400 30px/1 Poppins,sans-serif;color:#c9953a}.hero-location{margin-top:30px;color:#c9953a;font-size:10px;font-weight:700;letter-spacing:.25em;text-transform:uppercase}.hero-location p{margin:0}.hero-location .hero-city{margin-top:10px;color:#996014;font-size:9px;letter-spacing:.3em}.hero-scroll{position:absolute;z-index:2;bottom:12%;left:50%;transform:translateX(-50%);display:flex;align-items:center;flex-direction:column;gap:10px;color:#fff}.hero-scroll>span{display:block;width:21px;height:36px;border:2px solid white;border-radius:15px}.hero-scroll>span:before{content:'';display:block;width:2px;height:8px;background:white;margin:6px auto;border-radius:2px;animation:float 2s ease-in-out infinite}#opening.leaving{opacity:0;pointer-events:none}#seal-wrap{transition:opacity .65s}#seal-wrap.leaving{opacity:0;pointer-events:none}.reveal{opacity:0;transform:translate(var(--reveal-x,0px),30px);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.7,.3,1)}.reveal.visible{opacity:1;transform:none}.swing{animation:swing 5s ease-in-out infinite alternate}.spin{animation:spin 100s linear infinite}.float{animation:float 4s ease-in-out infinite}.seal-ring{animation:ring 2.6s ease-out infinite}.petal-field{position:fixed;inset:0;pointer-events:none;overflow:hidden}.petal-field i{position:absolute;top:-40px;opacity:.5;animation:petals var(--duration) linear var(--delay) infinite}.gate{transition:transform 1.2s cubic-bezier(.4,0,.2,1),opacity 1.2s;backface-visibility:hidden}.gate-ring{position:absolute;top:50%;width:48px;height:96px;margin-top:-48px;border:4px solid #c9953a}.gate-left .gate-ring{right:0;border-right:0;border-radius:48px 0 0 48px}.gate-right .gate-ring{left:0;border-left:0;border-radius:0 48px 48px 0}#date-gates.open .gate-left{transform:rotateY(-110deg);opacity:0}#date-gates.open .gate-right{transform:rotateY(110deg);opacity:0}#date-gates.open #open-date{display:none}.gallery-arrow{position:absolute;top:50%;transform:translateY(-50%);z-index:20;width:40px;height:40px;border-radius:50%;background:#fdfaf5;border:1px solid #c9953a59;box-shadow:0 4px 12px #6b4f2c1f;font-size:28px;line-height:1}#gallery-photo{transition:opacity .4s,transform .65s}#gallery-dots button{width:10px;height:10px;border-radius:50%;background:#c9953a40;border:0;margin:6px}#gallery-dots button[aria-current=true]{background:#c9953a;transform:scale(1.3);outline:1px solid #c9953a66;outline-offset:4px}#fmi-rsvp input,#fmi-rsvp select,#fmi-rsvp textarea{width:100%;padding:12px 16px;border:1px solid #e6d6c3;border-radius:12px;background:#fdfaf5;color:#6b4f2c;font:400 14px Poppins,sans-serif;letter-spacing:normal;text-transform:none}#fmi-rsvp input:focus,#fmi-rsvp textarea:focus{outline:1px solid #c9953a}#gift-dialog{background:#fdfaf5;color:#6b4f2c;border:1px solid #c9953a;border-radius:24px;max-width:min(90vw,360px);padding:32px;text-align:center}#gift-dialog::backdrop{background:#3d230966}#gift-dialog button{margin-top:20px;background:#c9953a;color:white;padding:10px 24px;border-radius:20px}@keyframes swing{from{transform:rotate(-5deg)}to{transform:rotate(5deg)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes float{50%{transform:translateY(-8px)}}@keyframes ring{from{transform:scale(.9);opacity:.7}to{transform:scale(1.35);opacity:0}}@keyframes petals{to{transform:translate(35px,115vh) rotate(280deg)}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}'''
