script='''(()=>{const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;let opening=false,opened=false,editing=false;
function finish(){if(opened)return;opened=true;$('#opening').classList.add('leaving');document.body.classList.remove('closed');$('#hero-video').play().catch(()=>{});setTimeout(()=>$('#opening').hidden=true,700)}
function open(){if(opening)return;opening=true;$('#seal-wrap').classList.add('leaving');const v=$('#intro-video');if(v.error)v.load();v.currentTime=0;v.play().catch(retryIntro)}
function retryIntro(){if(opened)return;opening=false;$('#seal-wrap').classList.remove('leaving');$('#open-invitation').setAttribute('aria-label','Retry opening invitation');}$('#open-invitation').onclick=open;$('#intro-video').addEventListener('ended',()=>{if(opening)finish()});$('#intro-video').addEventListener('error',retryIntro);addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='editing'){editing=Boolean(e.data.enabled);if(editing)finish()}});
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});all('.reveal').forEach(e=>observer.observe(e));$('#open-date').onclick=()=>$('#date-gates').classList.add('open');
let photos=GALLERY,slide=0;function show(){const image=$('#gallery-photo');if(!photos.length)return;slide=(slide+photos.length)%photos.length;image.src=photos[slide];image.alt='Wedding memory '+(slide+1);image.animate([{opacity:.3,transform:'scale(1.025)'},{opacity:1,transform:'scale(1)'}],{duration:reduced()?0:650});$('#gallery-dots').replaceChildren(...photos.map((_,i)=>{const b=document.createElement('button');b.setAttribute('aria-label','Go to slide '+(i+1));b.setAttribute('aria-current',String(slide===i));b.onclick=()=>{slide=i;show()};return b}))}
$('#previous-photo').onclick=()=>{slide--;show()};$('#next-photo').onclick=()=>{slide++;show()};let x=0;$('#gallery-frame').addEventListener('pointerdown',e=>x=e.clientX);$('#gallery-frame').addEventListener('pointerup',e=>{if(Math.abs(e.clientX-x)>35){slide+=e.clientX<x?1:-1;show()}});setInterval(()=>{if(!editing&&!document.hidden&&!reduced()){slide++;show()}},5000);
function tick(){const d=window.fmiData||{},n=Math.max(0,Date.parse(d.date+'T'+(d.time||'00:00')+':00+05:30')-Date.now());[Math.floor(n/86400000),Math.floor(n/3600000)%24,Math.floor(n/60000)%60,Math.floor(n/1000)%60].forEach((v,i)=>$('#count-'+i).textContent=Number.isFinite(v)?String(v).padStart(2,'0'):'00')};setInterval(tick,1000);
document.addEventListener('fmi:updated',()=>{const d=window.fmiData;$('#initials').replaceChildren(document.createTextNode((d.groom||'A')[0]+' & '+(d.bride||'M')[0]));photos=d.photos?.length?d.photos:GALLERY;show();tick();const cards=[];['preEvents','timeline'].forEach(list=>(d[list]||[]).forEach((e,i)=>{const card=$('#event-template').content.firstElementChild.cloneNode(true),j=cards.length;card.querySelector('.event-art').src=ART[j%ART.length];card.querySelector('.event-number').textContent='Event '+String(j+1).padStart(2,'0');const date=new Date(e.time);[['.event-title','title',e.title],['.event-time','time',Number.isNaN(+date)?'Time to be confirmed':date.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})+' Onwards'],['.event-description','description',e.description]].forEach(([sel,key,value])=>{const node=card.querySelector(sel);node.textContent=value;node.dataset.editEvent=list+'.'+i+'.'+key});card.querySelector('.event-date').textContent=Number.isNaN(+date)?'':date.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'});card.querySelector('.event-map').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.venue+' '+d.address);cards.push(card)}));$('#event-cards').replaceChildren(...cards)});
$('#gift-open').onclick=()=>$('#gift-dialog').showModal();$('#gift-close').onclick=()=>$('#gift-dialog').close();document.addEventListener('visibilitychange',()=>{if(document.hidden)all('video').forEach(v=>v.pause());else if(opening&&!opened)$('#intro-video').play().catch(retryIntro);else if(opened)all('video[loop]').forEach(v=>v.play().catch(()=>{}))});show();})();'''.replace('GALLERY',json.dumps(gallery_urls)).replace('ART',json.dumps([asset('ring-bg.png'),asset('wedding-bg.png'),asset('reception-bg.png')]))
